  "M29-3-4": "<div class=\"flex flex-wrap justify-center gap-5 p-3 border border-slate-300 rounded-xl\"><div class=\"text-center\"><div class=\"grid grid-cols-5 gap-1 text-xl\" aria-label=\"左边\"><span>🐟</span><span>🐟</span><span>🐟</span></div><div class=\"mt-2 text-sm text-slate-700\">一部分</div></div><div class=\"text-center\"><div class=\"grid grid-cols-5 gap-1 text-xl\" aria-label=\"右边\"><span>🐟</span><span>🐟</span><span>🐟</span><span>🐟</span></div><div class=\"mt-2 text-sm text-slate-700\">另一部分</div></div></div><div class=\"flex flex-wrap justify-center gap-3 p-3 border border-slate-300 rounded-xl bg-white text-sm text-slate-800\"><span class=\"px-3 py-2 border border-slate-300 rounded-lg\">合起来7个</span></div>",
